// Layer 1: regex for structured identifiers.
const patterns = {
  SSN: /\b\d{3}-\d{2}-\d{4}\b/g,
  PHONE_EG: /\b(?:\+?20[ -]?|0)1[0125]\d{8}\b/g,
  PHONE_INTL: /\b(?:\+?\d{1,3}[ -]?)?\(?\d{3}\)?[ -]?\d{3}[ -]?\d{4}\b/g,
  NATIONAL_ID_EG: /\b[23]\d{13}\b/g,
  EMAIL: /\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g,
  MRN: /\bMRN[:# ]?\s?\d{6,10}\b/gi,
  DATE: /\b\d{1,2}[\/-]\d{1,2}[\/-]\d{2,4}\b/g,
  IP: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g,
  URL: /\bhttps?:\/\/[^\s]+\b/g,
  ACCOUNT: /\bACCT[:# ]?\s?\d{6,12}\b/gi
};

const out = [];
for (const item of $input.all()) {
  const text = item.json.chatInput
    || item.json.text
    || item.json.body?.text
    || '';

  const spans = [];
  for (const [type, re] of Object.entries(patterns)) {
    for (const m of text.matchAll(re)) {
      spans.push({
        type,
        start: m.index,
        end: m.index + m[0].length,
        value: m[0],
        source: 'regex'
      });
    }
  }

  out.push({
    json: {
      request_id: item.json.request_id || $execution.id,
      text: text,
      spans: spans
    }
  });
}

return out;

const inputData = $input.item.json;

// جلب النص القادم من الـ Guardian أو الـ Output Validator بأي مسمى كان
let textToProcess = inputData.output || inputData.text || inputData.validatedOutput || inputData.finalResponse || "";
const mapping = inputData.mapping || {};

let restoredCount = 0;

// استبدال التوكينات بالبيانات الأصلية
if (mapping && typeof mapping === 'object' && Object.keys(mapping).length > 0) {
  for (const [token, originalValue] of Object.entries(mapping)) {
    if (textToProcess.includes(token)) {
      textToProcess = textToProcess.split(token).join(originalValue);
      restoredCount++;
    }
  }
}

return {
  json: {
    finalAnswer: textToProcess, // اسم المتغير الثابت والمضمون
    tokens_restored: restoredCount,
    request_id: inputData.request_id || ""
  }
};

// De-identification node.
// Inputs: spans from the regex node + entities from the Presidio node.
// Token format: [TYPE_<timeCode>_<rand>]
const REGEX_NODE = 'Regex detect';
const PRESIDIO_NODE = 'Presidio analyze';

// --- Input 1: regex node (carries the original text and its spans) ---
const base = $(REGEX_NODE).first().json;
const text = base.text || '';
const regexSpans = (base.spans || []).map(s => ({ ...s, source: 'regex', score: s.score ?? 1 }));

// --- Input 2: Presidio node ---
// The HTTP Request node may hand back one item holding an array,
// or one item per entity. Handle both, and fall back to $input.
let presidioItems;
try {
  presidioItems = $(PRESIDIO_NODE).all().map(i => i.json);
} catch (e) {
  presidioItems = $input.all().map(i => i.json);
}

let rawEntities = [];
if (presidioItems.length === 1 && Array.isArray(presidioItems[0])) {
  rawEntities = presidioItems[0];
} else if (presidioItems.length === 1 && Array.isArray(presidioItems[0]?.results)) {
  rawEntities = presidioItems[0].results;
} else {
  rawEntities = presidioItems.filter(x => x && x.entity_type);
}

const nerSpans = rawEntities
  .filter(r => typeof r.start === 'number' && typeof r.end === 'number')
  .map(r => ({
    type: r.entity_type,
    start: r.start,
    end: r.end,
    value: text.slice(r.start, r.end),
    source: 'presidio',
    score: r.score
  }));

// --- Merge both layers, drop overlaps ---
const all = [...regexSpans, ...nerSpans].sort(
  (a, b) => a.start - b.start
    || (b.end - b.start) - (a.end - a.start)
    || (b.score || 1) - (a.score || 1)
);

const merged = [];
for (const s of all) {
  if (!merged.length || s.start >= merged[merged.length - 1].end) merged.push(s);
}

// --- Time-coded random tokens ---
const issuedAt = Date.now();
const timeCode = issuedAt.toString(36).toUpperCase();
let counter = 0;
const randomSuffix = () => {
  counter++;
  const a = Math.floor(Math.random() * 0x100000000).toString(16).padStart(8, '0');
  const b = (issuedAt ^ (counter * 0x9e3779b1)).toString(16).slice(-4);
  return (a + b).toUpperCase().slice(0, 6);
};

// One token per distinct value, so repeated mentions stay linked.
const byValue = new Map();
const mapping = {};
const identifiers = [];

for (const s of merged) {
  const dedupeKey = s.type + '|' + s.value.trim().toLowerCase().replace(/\s+/g, ' ');
  if (!byValue.has(dedupeKey)) {
    const token = `[${s.type}_${timeCode}_${randomSuffix()}]`;
    byValue.set(dedupeKey, token);
    mapping[token] = s.value;
    identifiers.push({
      token,
      entity_type: s.type,
      detected_by: s.source,
      score: s.score,
      issued_at: new Date(issuedAt).toISOString(),
      occurrences: 1
    });
  } else {
    identifiers.find(x => x.token === byValue.get(dedupeKey)).occurrences++;
  }
  s.token = byValue.get(dedupeKey);
}

// Replace right-to-left so earlier offsets stay valid.
let deidentified = text;
for (let i = merged.length - 1; i >= 0; i--) {
  const s = merged[i];
  deidentified = deidentified.slice(0, s.start) + s.token + deidentified.slice(s.end);
}

const counts = merged.reduce((acc, s) => { acc[s.type] = (acc[s.type] || 0) + 1; return acc; }, {});

return [{ json: {
  request_id: base.request_id || $execution.id,
  mode: 'tokenize',
  reversible: true,
  issued_at: new Date(issuedAt).toISOString(),
  time_code: timeCode,
  expires_at: new Date(issuedAt + 300000).toISOString(),
  deidentified_text: deidentified,
  identifiers,
  mapping,
  entity_counts: counts,
  detected_by_regex: regexSpans.length,
  detected_by_presidio: nerSpans.length,
  dropped_as_overlap: (regexSpans.length + nerSpans.length) - merged.length,
  total_entities: merged.length,
  distinct_entities: Object.keys(mapping).length,
  recognizers: [...new Set(merged.map(s => s.source))]
}}];

const inputItem = $input.item.json;

// جلب النص المجهل
const deidentifiedText = inputItem.deidentified_text || inputItem.deidentified || inputItem.text || "";
const mapping = inputItem.mapping || {};
const requestId = inputItem.request_id || $execution.id;

// 1. Canonicalization
const normalizedText = deidentifiedText.normalize('NFKC').toLowerCase();

// 2. Blacklist Check
const maliciousPatterns = [
  /ignore\s+(all\s+)?instructions/i,
  /disregard\s+(all\s+)?previous/i,
  /dev\s*mode/i,
  /jailbreak/i,
  /\bdan\b/i,
  /system\s*prompt/i,
  /you\s+are\s+now/i,
  /act\s+as\s+a/i,
  /forget\s+(everything|your\s+role)/i,
  /override\s+(dosage|schedule|medication)/i,
  /delete\s+(all\s+)?calendar/i,
  /bypass\s+validation/i
];

let isBlocked = false;
let detectedPattern = "";

for (let i = 0; i < maliciousPatterns.length; i++) {
  if (maliciousPatterns[i].test(normalizedText)) {
    isBlocked = true;
    detectedPattern = maliciousPatterns[i].toString();
    break;
  }
}

// 3. Sanitization
const sanitizedText = deidentifiedText.replace(/[<>{}]/g, '');

// 4. Return Output (تم تصحيح علامات التنصيص هنا)
return {
  json: {
    isBlocked: isBlocked,
    sanitizedInput: sanitizedText,
    blockReason: isBlocked ? ("Malicious pattern detected: " + detectedPattern) : null,
    mapping: mapping,
    request_id: requestId,
    originalDeidentified: deidentifiedText
  }
};

const inputItem = $input.item.json;

// Safe fallback extraction across all node outputs
const sanitizedInput = inputItem.sanitizedInput || inputItem.guardrailsInput || inputItem.text || "";

// Safe string concatenation using standard quotes
const formattedUserInput = "<user_input>\n" + sanitizedInput + "\n</user_input>";

return {
  json: {
    formattedPrompt: formattedUserInput,
    mapping: inputItem.mapping || {},
    request_id: inputItem.request_id || ""
  }
};

const agentOutput = $json.output || $json.text || "";
const mapping = $json.mapping || {};
const requestId = $json.request_id || "";

let isOutputViolating = false;
let violationReason = null;

// 1. فحص تسريب التعليمات (System Prompt Leakage Check)
const leakagePatterns = [
  /<system_instructions>/i,
  /CRITICAL SECURITY RULES/i,
  /You are an expert Clinical Medication Management Assistant/i
];

for (const pattern of leakagePatterns) {
  if (pattern.test(agentOutput)) {
    isOutputViolating = true;
    violationReason = "System prompt leakage detected in output.";
    break;
  }
}

// 2. فحص السلامة الدوائية (Dosing & Refusal Rules)
// التأكد من عدم إعطاء جرعات صريحة بدون إخلاء مسؤولية طبي معتمد
const hasDosingNumbers = /\b\d+(\.\d+)?\s*(mg|g|ml|mcg|units|كبسولة|قرص|قرصين)\b/i.test(agentOutput);
const hasDisclaimer = /طبيب|صيدلي|استشارة|prescribed|physician|consult/i.test(agentOutput);

if (hasDosingNumbers && !hasDisclaimer) {
  // إضافة إخلاء مسؤولية تلقائي حمايةً للمريض
  var safeOutput = agentOutput + "\n\nتنبيّه طبي: يرجى مراجعة الطبيب أو الصيدلي لتأكيد الجرعة المحددة.";
} else {
  var safeOutput = agentOutput;
}

return {
  json: {
    isOutputViolating: isOutputViolating,
    validatedOutput: isOutputViolating ? "عذراً، تعذر إظهار الرد لدواعي أمان المخرجات الطبية." : safeOutput,
    violationReason: violationReason,
    mapping: mapping,
    request_id: requestId
  }
};
